<script setup>
import {ref,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {auth,can,logout} from '../stores/auth.js'
const collapsed=ref(true),mobile=ref(false),route=useRoute(),router=useRouter()
const items=computed(()=>[{to:'/scale',label:'Bàscula',icon:'B',p:'scale.view'},{to:'/',label:'Inici',icon:'⌂',p:'dashboard.view'},{to:'/time-clock',label:'Fitxatge',icon:'H',p:'time_clock.view'},{to:'/sales-clients',label:'Vendes clients',icon:'€',p:'sales_clients.view'},{to:'/accounting',label:'Comptabilitat',icon:'▤',p:'accounting.view'},{to:'/users',label:'Usuaris',icon:'U',p:'users.view'},{to:'/roles',label:'Rols i permisos',icon:'R',p:'roles.view'},{to:'/company',label:'Configuració',icon:'⚙',p:'company.view'},{to:'/audit',label:'Auditoria',icon:'A',p:'audit.view'}].filter(x=>can(x.p)))
async function signout(){await logout();router.push('/login')}
</script>
<template><div class="shell" :class="{collapsed:collapsed&&!mobile}"><div v-if="mobile" class="backdrop" @click="mobile=false"></div><aside class="sidebar" :class="{open:mobile}"><div class="brand"><span class="brand-mark">RBC</span><span class="brand-name">Reciclajes<br>Bajo Cinca</span></div><nav aria-label="Navegació principal"><RouterLink v-for="item in items" :key="item.to" :to="item.to" :title="item.label" :aria-label="item.label" @click="mobile=false"><span class="nav-icon">{{item.icon}}</span><span>{{item.label}}</span></RouterLink></nav><button class="collapse" @click="collapsed=!collapsed" :aria-label="collapsed?'Ampliar menú':'Col·lapsar menú'">{{collapsed?'›':'‹'}} <span>Col·lapsar</span></button></aside><div class="workspace"><header><button class="icon-button mobile-menu" @click="mobile=true" aria-label="Obrir menú">☰</button><div><p class="eyebrow">Reciclajes Bajo Cinca</p><h1>{{route.meta.title}}</h1></div><div class="profile"><div><strong>{{auth.user.name}}</strong><small>{{auth.user.role_name}}</small></div><button class="button secondary" @click="signout">Tancar sessió</button></div></header><main><RouterView/></main></div></div></template>
